static PyObject *py_kong_gbm(PyObject *self, PyObject *args) {
    PyObject *obj;
    if (!PyArg_ParseTuple(args, "O", &obj)) return NULL;
    PyObject *fast = PySequence_Fast(obj, "features must be a sequence");
    if (!fast) return NULL;
    if (PySequence_Fast_GET_SIZE(fast) != 21) {
        Py_DECREF(fast);
        PyErr_SetString(PyExc_ValueError, "21 features");
        return NULL;
    }
    double x[21];
    for (int i = 0; i < 21; i++) {
        x[i] = PyFloat_AsDouble(PySequence_Fast_GET_ITEM(fast, i));
        if (x[i] == -1.0 && PyErr_Occurred()) {
            Py_DECREF(fast);
            return NULL;
        }
    }
    Py_DECREF(fast);
    double s = 0.12013278721682846;
    for (int t = 0; t < 300; t++) {
        int n = KONG_ROOT[t];
        while (!KONG_LEAF[n]) n = x[KONG_FEAT[n]] <= KONG_THR[n] ? KONG_LEFT[n] : KONG_RIGHT[n];
        s += KONG_VAL[n];
    }
    return PyFloat_FromDouble(s);
}

static PyMethodDef native_methods[] = {
    {"race_profile", py_race_profile, METH_VARARGS,
     "Register a race profile in this module's own table (the runtime's ids do not carry over)."},
    {"shape_constants", py_shape_constants, METH_VARARGS, "Set the strategy's shape correction constants."},
    {"fish_gbm", py_fish_gbm, METH_VARARGS, "fish_gbm(features): the fitted correction to going on at a win holding a white."},
    {"kong_gbm", py_kong_gbm, METH_VARARGS, "kong_gbm(features): the fitted gain of keeping a kong tile over melding it."},
    {"mimic_features", py_mimic_features, METH_VARARGS, "mimic_features(held, opened, available, tile): the distilled correction's features."},
    {"call_net", py_call_net, METH_VARARGS,
     "call_net(held, opened, available, options, wall, dealer, ahead): each response option's distilled score."},
    {"feed_rate", py_feed_rate, METH_VARARGS,
     "feed_rate(stage, tile, chi): opponents' discards of a tile per round over my chance of drawing it."},
    {"call_option", py_call_option, METH_VARARGS,
     "call_option(hand, opened, available, draws, stage, chis, profile, fallback, q, weight): the value "
     "calls add to a hand not yet waiting."},
    {"reshape_gain", py_reshape_gain, METH_VARARGS,
     "reshape_gain(hand, opened, available, draws, profile, fallback, q, speed): the option of a hand one "
     "step away to trade a non-improving draw for a better hand one step away."},
    {NULL, NULL, 0, NULL},
};

static struct PyModuleDef native_module = {PyModuleDef_HEAD_INIT, "native", NULL, -1, native_methods};

PyMODINIT_FUNC PyInit_native(void) {
    if (fast_keys() < 0) return NULL;
    return PyModule_Create(&native_module);
}
